import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { MAX_ATTACHMENT_COUNT, MESSAGE_TYPES, SOCKET_EVENTS, UploadStatus } from '@/lib/constants';
import {
  useApi,
  useAttachmentUpload,
  useScreenshotContext,
  useSocketContext,
  useSupportAssistantContext,
} from '@/lib/hooks';
import type {
  TAttachment,
  TConversationListItem,
  TMessage,
  TRawConversation,
  TSocketMessage,
  TSupportAssistantContext,
} from '@/lib/types';
import {
  buildValidatedAttachments,
  generateUUID,
  parseConversationMessages,
  revalidateAttachments,
} from '@/lib/utils';

type TUseChatProps = {
  welcomeMessage: string;
  supportProjectId: number | null;
  initialHistory: TConversationListItem[];
  initialConversation: TRawConversation | null;
  isInitLoading: boolean;
  showToast: (message: string) => void;
};

export const useChat = (props: TUseChatProps) => {
  const { welcomeMessage, supportProjectId, initialHistory, initialConversation, isInitLoading, showToast } =
    props;

  const hasInitializedRef = useRef(false);

  const api = useApi();
  const socket = useSocketContext();
  const supportAssistantContext = useSupportAssistantContext();
  const screenshotContext = useScreenshotContext();

  const { uploadAttachments, isUploading } = useAttachmentUpload();

  const createWelcomeMessages = useCallback(
    (): TMessage[] =>
      welcomeMessage
        ? [{ id: 'welcome', role: 'assistant' as const, content: welcomeMessage, timestamp: Date.now() }]
        : [],
    [welcomeMessage],
  );

  const [messages, setMessages] = useState<TMessage[]>([]);
  const [inputText, setInputText] = useState('');
  const [attachments, setAttachments] = useState<TAttachment[]>([]);
  const [currentConversationId, setCurrentConversationId] = useState<string | null>(null);
  const [history, setHistory] = useState<TConversationListItem[]>([]);
  const [isSwitchingConversation, setIsSwitchingConversation] = useState(false);

  const isLoading = useMemo(
    () => isInitLoading || isSwitchingConversation,
    [isInitLoading, isSwitchingConversation],
  );

  const isStreaming = useMemo(() => messages.some(m => m.isStreaming), [messages]);

  const handleAnimationComplete = useCallback((messageId: string) => {
    setMessages(prev => prev.map(m => (m.id === messageId ? { ...m, isAnimating: false } : m)));
  }, []);

  const handleStop = useCallback(() => {
    const streamingMessageIndex = messages.findIndex(m => m.isStreaming);
    if (streamingMessageIndex === -1) return;

    const streamingMessage = messages[streamingMessageIndex];

    // Find the preceding user message (the interrupted question)
    let userMessageIndex = -1;
    let userMessageContent = '';
    for (let i = streamingMessageIndex - 1; i >= 0; i--) {
      if (messages[i].role === 'user') {
        userMessageIndex = i;
        userMessageContent = messages[i].content;
        break;
      }
    }

    // Use Socket.IO to stop the task - RPC handles all backend cleanup
    socket?.emit(SOCKET_EVENTS.STOP, { message_id: streamingMessage.id });

    // Update UI: remove empty assistant message and the user message, restore input
    setTimeout(() => {
      setMessages(prev => {
        const idsToRemove = new Set<string>();

        // Remove the streaming assistant message if it's empty or has no meaningful content
        if (!streamingMessage.content?.trim()) {
          idsToRemove.add(streamingMessage.id);
        }

        // Remove the user message that triggered this response
        if (userMessageIndex !== -1) {
          idsToRemove.add(messages[userMessageIndex].id);
        }

        return prev
          .filter(m => !idsToRemove.has(m.id))
          .map(m =>
            m.id === streamingMessage.id
              ? { ...m, isStreaming: false, taskId: undefined, statusMessage: undefined }
              : m,
          );
      });

      // Restore the interrupted question to the input field
      if (userMessageContent) {
        setInputText(userMessageContent);
      }
    }, 200);
  }, [messages, socket]);

  const enterRoom = useCallback(
    (conversationId: string) => {
      socket?.emit(SOCKET_EVENTS.ENTER_ROOM, {
        project_id: supportProjectId,
        conversation_id: conversationId,
      });
    },
    [socket, supportProjectId],
  );

  const leaveRoom = useCallback(
    (conversationId: string) => {
      socket?.emit(SOCKET_EVENTS.LEAVE_ROOM, {
        project_id: supportProjectId,
        conversation_id: conversationId,
      });
    },
    [socket, supportProjectId],
  );

  const emitPredict = useCallback(
    (params: {
      conversation_uuid: string;
      content: string;
      attachments?: string[];
      support_assistant_context?: TSupportAssistantContext;
    }) => {
      socket?.emit(SOCKET_EVENTS.PREDICT, params);
    },
    [socket],
  );

  const handlePredict = useCallback((message: TSocketMessage) => {
    const { message_id, type, content, response_metadata } = message;

    const mapStepToStatusMessage = (stepType: string): string => {
      if (stepType === MESSAGE_TYPES.START_TASK || stepType === MESSAGE_TYPES.AGENT_START)
        return 'Starting up...';
      if (stepType === MESSAGE_TYPES.AGENT_LLM_START) return 'Looking things up...';
      if (stepType === MESSAGE_TYPES.AGENT_TOOL_START) return 'Consulting knowledge base...';
      if (stepType === MESSAGE_TYPES.AGENT_LLM_CHUNK) return 'Writing response...';
      return '';
    };

    if (
      type === MESSAGE_TYPES.AGENT_START ||
      type === MESSAGE_TYPES.AGENT_LLM_START ||
      type === MESSAGE_TYPES.AGENT_TOOL_START ||
      type === MESSAGE_TYPES.AGENT_LLM_CHUNK ||
      type === MESSAGE_TYPES.CHUNK ||
      type === MESSAGE_TYPES.AI_MESSAGE_CHUNK ||
      type === MESSAGE_TYPES.AGENT_RESPONSE ||
      type === MESSAGE_TYPES.ERROR ||
      type === MESSAGE_TYPES.AGENT_EXCEPTION
    ) {
      setMessages(prev => {
        const existing = prev.find(m => m.id === message_id);
        if (!existing) {
          return [
            ...prev,
            {
              id: message_id,
              role: 'assistant' as const,
              content: '',
              timestamp: Date.now(),
              isStreaming: true,
            },
          ];
        }
        if (!existing.isStreaming) {
          return prev.map(m => (m.id === message_id ? { ...m, isStreaming: true } : m));
        }
        return prev;
      });
    }

    switch (type) {
      case MESSAGE_TYPES.START_TASK: {
        const taskId = (content as { task_id?: string })?.task_id;
        setMessages(prev => [
          ...prev,
          {
            id: message_id,
            role: 'assistant',
            content: '',
            timestamp: Date.now(),
            isStreaming: true,
            taskId,
            statusMessage: mapStepToStatusMessage(type),
          },
        ]);
        break;
      }

      case MESSAGE_TYPES.AGENT_START:
        setMessages(prev =>
          prev.map(m => (m.id === message_id ? { ...m, statusMessage: mapStepToStatusMessage(type) } : m)),
        );
        break;

      case MESSAGE_TYPES.AGENT_LLM_START:
      case MESSAGE_TYPES.AGENT_TOOL_START:
        setMessages(prev =>
          prev.map(m => (m.id === message_id ? { ...m, statusMessage: mapStepToStatusMessage(type) } : m)),
        );
        break;

      case MESSAGE_TYPES.AGENT_TOOL_END:
      case MESSAGE_TYPES.AGENT_LLM_END:
      case MESSAGE_TYPES.AGENT_ON_TRANSITIONAL_EDGE:
      case MESSAGE_TYPES.AGENT_ON_FUNCTION_TOOL_NODE:
        break;

      case MESSAGE_TYPES.CHUNK:
      case MESSAGE_TYPES.AI_MESSAGE_CHUNK: {
        const chunk = typeof content === 'string' ? content : JSON.stringify(content);
        const finished = !!response_metadata?.finish_reason;

        setMessages(prev =>
          prev.map(m =>
            m.id === message_id
              ? {
                  ...m,
                  content: m.content + chunk,
                  statusMessage: undefined,
                  ...(finished && { isStreaming: false }),
                }
              : m,
          ),
        );
        break;
      }

      case MESSAGE_TYPES.AGENT_LLM_CHUNK:
        setMessages(prev =>
          prev.map(m =>
            m.id === message_id && m.statusMessage !== mapStepToStatusMessage(type)
              ? { ...m, statusMessage: mapStepToStatusMessage(type) }
              : m,
          ),
        );
        break;

      case MESSAGE_TYPES.AGENT_RESPONSE: {
        const responseContent = typeof content === 'string' ? content : JSON.stringify(content);
        setMessages(prev =>
          prev.map(m => {
            if (m.id !== message_id) return m;

            return {
              ...m,
              content: responseContent,
              isStreaming: false,
              statusMessage: undefined,
            };
          }),
        );
        break;
      }

      case MESSAGE_TYPES.PIPELINE_FINISH:
        setMessages(prev =>
          prev.map(m =>
            m.id === message_id && m.isStreaming ? { ...m, isStreaming: false, statusMessage: undefined } : m,
          ),
        );
        break;

      case MESSAGE_TYPES.ERROR:
      case MESSAGE_TYPES.AGENT_EXCEPTION:
        setMessages(prev =>
          prev.map(m =>
            m.id === message_id
              ? {
                  ...m,
                  content: typeof content === 'string' ? content : 'An error occurred',
                  isStreaming: false,
                  isAnimating: false,
                  isError: true,
                  statusMessage: undefined,
                }
              : m,
          ),
        );
        break;
    }
  }, []);

  const handleError = useCallback((data: { error: string; code: string }) => {
    setMessages(prev => [
      ...prev,
      {
        id: generateUUID(),
        role: 'assistant' as const,
        content: data.error || 'An error occurred',
        timestamp: Date.now(),
        isError: true,
      },
    ]);
  }, []);

  const handleConversationNameUpdated = useCallback((data: { conversation_uuid: string; name: string }) => {
    const name = data.name.replace(/^User ID \d+\s*-\s*/, '');
    setHistory(prev => prev.map(item => (item.uuid === data.conversation_uuid ? { ...item, name } : item)));
  }, []);

  useEffect(() => {
    if (isInitLoading || hasInitializedRef.current) return;
    hasInitializedRef.current = true;

    setHistory(initialHistory);

    if (initialHistory.length > 0 && initialConversation) {
      const parsed = parseConversationMessages(initialConversation);
      setMessages(parsed.length > 0 ? parsed : createWelcomeMessages());
      setCurrentConversationId(initialHistory[0].uuid);
      enterRoom(initialHistory[0].uuid);
    } else {
      setMessages(createWelcomeMessages());
    }
  }, [isInitLoading, initialHistory, initialConversation, createWelcomeMessages, enterRoom]);

  useEffect(() => {
    if (!socket) return;

    socket.on(SOCKET_EVENTS.PREDICT_RESPONSE, handlePredict);
    socket.on(SOCKET_EVENTS.ERROR, handleError);
    socket.on(SOCKET_EVENTS.CONVERSATION_NAME_UPDATED, handleConversationNameUpdated);

    return () => {
      socket.off(SOCKET_EVENTS.PREDICT_RESPONSE, handlePredict);
      socket.off(SOCKET_EVENTS.ERROR, handleError);
      socket.off(SOCKET_EVENTS.CONVERSATION_NAME_UPDATED, handleConversationNameUpdated);
    };
  }, [socket, handlePredict, handleError, handleConversationNameUpdated]);

  useEffect(() => {
    if (!socket || !currentConversationId) return;

    const handleReconnect = () => {
      enterRoom(currentConversationId);
    };

    socket.io.on('reconnect', handleReconnect);

    return () => {
      socket.io.off('reconnect', handleReconnect);
    };
  }, [socket, currentConversationId, enterRoom]);

  const addFiles = useCallback(
    (files: File[]) => {
      const currentValidCount = attachments.filter(a => a.status !== UploadStatus.ERROR).length;
      const remaining = MAX_ATTACHMENT_COUNT - currentValidCount;

      if (remaining <= 0) {
        showToast(
          `You've reached the ${MAX_ATTACHMENT_COUNT}-file limit. Only the first ${MAX_ATTACHMENT_COUNT} will be processed.`,
        );
        return;
      }

      if (files.length > remaining) {
        showToast(
          `You've reached the ${MAX_ATTACHMENT_COUNT}-file limit. Only the first ${MAX_ATTACHMENT_COUNT} will be processed.`,
        );
        setAttachments(prev => buildValidatedAttachments(files.slice(0, remaining), prev));
        return;
      }

      setAttachments(prev => buildValidatedAttachments(files, prev));
    },
    [attachments, showToast],
  );

  const removeAttachment = useCallback((attachmentId: string) => {
    setAttachments(prev => revalidateAttachments(prev.filter(a => a.id !== attachmentId)));
  }, []);

  const updateAttachmentProgress = useCallback((attachmentId: string, progress: number) => {
    setAttachments(prev =>
      prev.map(a => (a.id === attachmentId ? { ...a, status: UploadStatus.UPLOADING, progress } : a)),
    );
  }, []);

  const markAttachmentCompleted = useCallback((attachmentId: string, filepath: string) => {
    setAttachments(prev =>
      prev.map(a =>
        a.id === attachmentId ? { ...a, status: UploadStatus.COMPLETED, progress: 100, filepath } : a,
      ),
    );
  }, []);

  const markAttachmentError = useCallback((attachmentId: string, error: string) => {
    setAttachments(prev =>
      prev.map(a => (a.id === attachmentId ? { ...a, status: UploadStatus.ERROR, error } : a)),
    );
  }, []);

  const clearAttachments = useCallback(() => {
    setAttachments([]);
  }, []);

  const startUpload = useCallback(
    async (conversationUuid: string): Promise<string[]> => {
      const pendingAttachments = attachments.filter(a => a.status === UploadStatus.PENDING);

      if (pendingAttachments.length === 0) return [];

      setAttachments(prev =>
        prev.map(a => (a.status === UploadStatus.PENDING ? { ...a, status: UploadStatus.UPLOADING } : a)),
      );

      const uploadedFilepaths: string[] = [];

      await uploadAttachments({
        conversationId: conversationUuid,
        attachments: pendingAttachments,
        onProgress: updateAttachmentProgress,
        onComplete: (attachmentId, filepath) => {
          markAttachmentCompleted(attachmentId, filepath);
          uploadedFilepaths.push(filepath);
        },
        onError: markAttachmentError,
      });

      return uploadedFilepaths;
    },
    [attachments, uploadAttachments, updateAttachmentProgress, markAttachmentCompleted, markAttachmentError],
  );

  const handleSend = useCallback(
    async (text: string) => {
      let activeConversationId = currentConversationId;

      // Create conversation if needed
      if (!activeConversationId) {
        try {
          const created = await api.createConversation();
          activeConversationId = created.uuid;
          setCurrentConversationId(activeConversationId);
          setHistory(prev => [created, ...prev]);
          enterRoom(activeConversationId);
        } catch {
          setMessages(prev => [
            ...prev,
            {
              id: generateUUID(),
              role: 'assistant',
              content: 'Failed to create conversation. Please try again.',
              timestamp: Date.now(),
              isError: true,
            },
          ]);
          return;
        }
      }

      const pendingAttachments = attachments.filter(a => a.status === UploadStatus.PENDING);
      const alreadyCompletedFilepaths = attachments
        .filter(a => a.status === UploadStatus.COMPLETED && a.filepath)
        .map(a => a.filepath as string);

      const uploadedFilepaths =
        pendingAttachments.length > 0 && activeConversationId ? await startUpload(activeConversationId) : [];

      if (pendingAttachments.length > 0 && uploadedFilepaths.length < pendingAttachments.length) return;

      setMessages(prev => [
        ...prev,
        { id: generateUUID(), role: 'user', content: text, timestamp: Date.now() },
      ]);

      const allFilepaths = [...alreadyCompletedFilepaths, ...uploadedFilepaths];

      const validScreenshot = screenshotContext?.getValidScreenshot();

      if (activeConversationId && validScreenshot) {
        try {
          const file = new File([validScreenshot], `screenshot-${Date.now()}.png`, {
            type: 'image/png',
          });
          const formData = new FormData();

          formData.append('file', file);
          formData.append('overwrite', '1');

          const response = await api.uploadFile(activeConversationId, formData);
          const result = (response as { filepath: string }[])[0];

          if (result?.filepath) allFilepaths.push(result.filepath);
        } catch {
          // screenshot upload is best-effort
        }
        screenshotContext?.clearScreenshot();
      }

      if (activeConversationId)
        emitPredict({
          conversation_uuid: activeConversationId,
          content: text,
          attachments: allFilepaths.length > 0 ? allFilepaths : undefined,
          support_assistant_context: supportAssistantContext ?? undefined,
        });

      clearAttachments();
    },
    [
      currentConversationId,
      api,
      enterRoom,
      emitPredict,
      attachments,
      startUpload,
      clearAttachments,
      supportAssistantContext,
      screenshotContext,
    ],
  );

  const handleNewChat = useCallback(() => {
    if (currentConversationId) leaveRoom(currentConversationId);

    setCurrentConversationId(null);
    setMessages(createWelcomeMessages());
    setInputText('');
    clearAttachments();
  }, [currentConversationId, leaveRoom, createWelcomeMessages, clearAttachments]);

  const handleSelectConversation = useCallback(
    async (conversationId: string) => {
      if (currentConversationId === conversationId) return;
      if (currentConversationId) leaveRoom(currentConversationId);

      setCurrentConversationId(conversationId);
      enterRoom(conversationId);
      setInputText('');
      clearAttachments();
      setMessages([]);
      setIsSwitchingConversation(true);

      try {
        const conversation = await api.getConversation(conversationId);
        const parsed = parseConversationMessages(conversation);
        setMessages(parsed.length > 0 ? parsed : createWelcomeMessages());
      } catch {
        setMessages(createWelcomeMessages());
      } finally {
        setIsSwitchingConversation(false);
      }
    },
    [currentConversationId, leaveRoom, enterRoom, createWelcomeMessages, api, clearAttachments],
  );

  return {
    messages,
    inputText,
    setInputText,
    attachments,
    addFiles,
    removeAttachment,
    history,
    currentConversationId: currentConversationId ?? '',
    isLoading,
    isStreaming,
    isUploading,
    handleNewChat,
    handleSelectConversation,
    handleSend,
    handleStop,
    handleAnimationComplete,
  };
};
